#!/usr/bin/env python3
import cadquery as cq
from pathlib import Path

SPEC = {'kind': 'extrusion', 'center': [-0.190375305, -0.215785775, 0.39564654], 'basis': [[0.0, 0.9999986787448584, -0.001625579446745248], [-0.9472670419262778, 0.0005209091945349552, 0.32044481573876427], [0.3204452391286841, 0.0015398578339345264, 0.947265790344828]], 'axis': [-0.001625579446745248, 0.32044481573876427, 0.947265790344828], 'zmin': -0.1044232686238834, 'zmax': 0.10436659788192673, 'profiles': [{'outer': [[-0.10426603760815344, -0.005971168614446271], [-0.10438989112643252, 0.005876064480817431], [-0.10214270508158962, 0.025466384637465377], [-0.10104029839475386, 0.027065546125336282], [-0.09558797310046946, 0.027114009901480125], [-0.07896834620299112, 0.03051038322221369], [-0.07855820375339899, 0.03053731601375062], [-0.017568778823565657, 0.030646499698588063], [-0.01735911028912959, 0.03087952635728818], [-0.01085973415948115, 0.03089802697185673], [-0.010409918215907216, 0.03189766189394503], [0.004874519198453734, 0.03191050154798432], [0.004874519198453734, 0.03252316783950778], [0.010627499288162088, 0.032520004232951163], [0.010627499288162088, 0.031453741527901445], [0.010820575798921046, 0.031064084897459182], [0.012265191386266751, 0.031056215586732043], [0.012265191386266751, 0.030895740997180652], [0.012454298277385263, 0.03089543350425829], [0.012454298277385263, 0.0311304357147894], [0.014092009320830781, 0.031132863177042502], [0.014092009320830781, 0.03259242319245021], [0.016287454770259047, 0.03259555210837965], [0.019844989410539138, 0.03258925958589359], [0.019844989410539138, 0.031133522429487085], [0.0214826815086438, 0.031093410862620432], [0.021792981782652106, 0.031093866621459854], [0.021792981782652106, 0.03255319441458082], [0.02741998482845466, 0.03255010008373799], [0.02741998482845466, 0.031094286836652208], [0.029141661622496522, 0.031086265253709673], [0.029141661622496522, 0.030640392563872205], [0.07905232463071024, 0.030532119961696035], [0.09548261101147361, 0.027115016502334638], [0.10023903810204159, 0.027050485876586056], [0.10144623925286314, 0.025450054421144876], [0.10209969118449436, 0.02177378936067922], [0.10203970959586953, 0.016323255449190072], [0.10229888657062497, 0.014584907223829414], [0.10426826385163344, 0.005873074391062194], [0.10438987510417053, 0.003787902673606402], [0.10438987510417053, -0.00596472444066786], [0.10222668977752679, -0.02546642082128778], [0.10108230341984524, -0.027065569207051388], [0.09553877102209135, -0.027114246234197857], [0.07905232463071024, -0.030599089268272744], [0.07855819428072852, -0.030625975891399062], [0.029141661622496522, -0.03072958365603481], [0.029141661622496522, -0.031064532629120564], [0.02741998482845466, -0.031066902413526755], [0.02741998482845466, -0.03257082387479272], [0.021792981782652106, -0.03256772954394989], [0.021792981782652106, -0.031067566338301027], [0.02002931264064167, -0.031027454793011628], [0.019844989410539138, -0.03102772465716466], [0.019844989410539138, -0.03253166437263712], [0.014092009320830781, -0.0325285007660805], [0.014092009320830781, -0.03102871796234579], [0.012454298277385263, -0.031020362168040837], [0.012454298277385263, -0.030851221062711896], [0.012265191386266751, -0.030851525749064305], [0.012265191386266751, -0.031094582296098194], [0.010814168227405623, -0.031096664309630793], [0.010627499288162088, -0.03150859234630775], [0.010627499288162088, -0.03260091972557955], [0.008319028675981109, -0.03260436678708079], [0.004874519198453734, -0.03259775611902293], [0.004874519198453734, -0.03186600889362396], [-0.004790563201901354, -0.03186586560684156], [-0.004790563201901354, -0.032523214110499375], [-0.01054353381893927, -0.03252005050915185], [-0.01054353381893927, -0.03157651753814504], [-0.010772788121258191, -0.031019761234856363], [-0.012181225917043932, -0.031011911921530366], [-0.012181225917043932, -0.030851503610477598], [-0.012384521841977565, -0.030851167313752894], [-0.012384521841977565, -0.031086200131682958], [-0.014022213940082228, -0.031088528181007123], [-0.014022213940082228, -0.032592537561164314], [-0.019157180864707947, -0.032594050115327296], [-0.019775194029790583, -0.032589373954607696], [-0.019775194029790583, -0.031089210869083943], [-0.021412886127895246, -0.031049121101818566], [-0.021583029515479597, -0.031049370209362166], [-0.021583029515479597, -0.03255330986889473], [-0.02733600013251751, -0.0325501462675472], [-0.02733600013251751, -0.03105036356677687], [-0.029099688219868806, -0.03104193839379375], [-0.029099688219868806, -0.030729074534090524], [-0.07896834620299112, -0.03062082600775509], [-0.09540579114073655, -0.02711505128168467], [-0.10021127324131682, -0.027050577235368824], [-0.10148824107350217, -0.02545002132404441], [-0.10215590154703634, -0.021773824540875116], [-0.10202266229867506, -0.01586792463813033], [-0.10221492082002863, -0.014584963397207202]], 'holes': []}], 'simplify_tolerance': 4.175595324612061e-05, 'sketch_entity_count': 96}
OUT = Path(__file__).resolve().parent

def vec(v):
    return cq.Vector(float(v[0]), float(v[1]), float(v[2]))

def build():
    s = SPEC
    kind = s["kind"]
    B = s.get("basis")
    center = s.get("center")
    if kind == "extrusion":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["zmin"] * axis[i] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        result = None
        height = s["zmax"] - s["zmin"]
        for profile in s["profiles"]:
            solid = cq.Workplane(plane).polyline(profile["outer"]).close().extrude(height)
            for hole in profile["holes"]:
                cutter = cq.Workplane(plane).polyline(hole).close().extrude(height)
                solid = solid.cut(cutter)
            result = solid if result is None else result.union(solid)
    elif kind == "multi_loft":
        def loft(track):
            wires = [cq.Wire.makePolygon([vec(p) for p in section], close=True) for section in track]
            return cq.Solid.makeLoft(wires, ruled=bool(s.get("ruled", True)))
        outer = [loft(track) for track in s["outer_tracks"]]
        # Keep disjoint solids as a legal STEP compound.  Global Boolean fusion
        # is unnecessary for training geometry and scales poorly with profiles.
        for track in s.get("hole_tracks", []):
            cutter = loft(track)
            cut_outer = []
            for solid in outer:
                try:
                    cut_outer.append(solid.cut(cutter))
                except Exception:
                    cut_outer.append(solid)
            outer = cut_outer
        result = outer[0] if len(outer) == 1 else cq.Compound.makeCompound(outer)
    elif kind == "box":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["mins"][0]*B[i][0] + s["mins"][1]*B[i][1] + s["mins"][2]*B[i][2] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        dx=s["maxs"][0]-s["mins"][0]; dy=s["maxs"][1]-s["mins"][1]; dz=s["maxs"][2]-s["mins"][2]
        result = cq.Workplane(plane).rect(dx,dy,centered=False).extrude(dz)
    elif kind == "cylinder":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["zmin"] * axis[i] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        result = cq.Workplane(plane).circle(s["radius"]).extrude(s["zmax"]-s["zmin"])
    else:
        raise ValueError(kind)
    cq.exporters.export(result, str(OUT / "reconstructed.step"))
    cq.exporters.export(result, str(OUT / "reconstructed.stl"), tolerance=0.001, angularTolerance=0.05)
    return result

if __name__ == "__main__":
    build()
